use super::*;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn close<T:crate::retirement::RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(error,_)|error).unwrap();for _ in 0..100000{if owner.terminal_is_empty(){return}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..*bank}).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(bank,fuel,p,owner.last_turn_work());}panic!("native backing cleanup exhausted finite turns")}
struct WorkLoan<'a>(&'a u64);
impl crate::native_decoding::NativeDecodeWorkRecipient for WorkLoan<'_>{fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|n|n<=(*self.0).min(1)))}}
fn funded_turn(control:&mut NativeDecodeControl<'_>,fuel:&u64,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{let mut loan=WorkLoan(fuel);control.with_work_recipient(&mut loan,|control|Ok::<_,ValueError>(operation(control))).unwrap()}
#[test]fn actual_native_backing_births_keep_null_denied_outputs_and_exact_cumulative_allocation(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(s["capacityBytes"].as_u64().unwrap()as usize,&mut callback);let mut values=None;let denied=control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(values.is_none());let missing=control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:1,..bank});assert_eq!(missing.work,0);assert_eq!(missing.result.unwrap_err().primary.unwrap().kind,ValueRefusalKind::UnsupportedOwner);assert!(values.is_none());let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||funded_turn(&mut control,&fuel,|control|control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:1,..bank}))));assert_eq!(turn.work,row["nullWork"].as_u64().unwrap());fuel-=turn.work;assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert!(turn.result.is_err());assert!(values.is_none());assert_eq!(control.owned_bytes(),row["nullOwnedBytes"].as_u64().unwrap()as usize);
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||funded_turn(&mut control,&fuel,|control|control.admit_vec::<u64>(&mut values,row["count"].as_u64().unwrap()as usize,RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(turn.work,row["birthWork"].as_u64().unwrap());let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,0);post(&mut bank,&mut fuel,p,turn.work);let first=control.owned_bytes();assert_eq!(first,p.retained_capacity_bytes);assert_eq!(serde_json::to_value(values.as_ref().unwrap()).unwrap(),serde_json::json!([]));let mut text=None;let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||funded_turn(&mut control,&fuel,|control|control.admit_string(&mut text,row["text"].as_str().unwrap().len(),RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(control.owned_bytes(),first+p.retained_capacity_bytes);post(&mut bank,&mut fuel,p,turn.work);assert_eq!(serde_json::to_value(text.as_ref().unwrap()).unwrap(),serde_json::json!(""));assert_eq!(control.actual_work(),row["observedBirthWork"].as_u64().unwrap());close(values.take().unwrap(),&mut bank,&mut fuel);close(text.take().unwrap(),&mut bank,&mut fuel);}
